$ErrorActionPreference = 'Stop'

$dest = Join-Path $PSScriptRoot '..\source\webassets\live2dcubismcore.min.js'
$dest = [IO.Path]::GetFullPath($dest)

$urls = @(
    'https://cubism.live2d.com/sdk-web/cubismcore/live2dcubismcore.min.js',
    'https://cdn.jsdelivr.net/gh/Live2D/CubismWebFramework@develop/Core/live2dcubismcore.min.js'
)

if (Test-Path -LiteralPath $dest) {
    $size = (Get-Item -LiteralPath $dest).Length
    Write-Host "已存在（$([math]::Round($size/1KB)) KB）：$dest" -ForegroundColor Green
    Write-Host "要重新下载请先删掉它。"
    exit 0
}

Write-Host "下载 Live2D Cubism Core …"
$ok = $false
foreach ($u in $urls) {
    try {
        Invoke-WebRequest $u -OutFile $dest -UseBasicParsing -TimeoutSec 60
        $size = (Get-Item -LiteralPath $dest).Length
        if ($size -lt 50KB) { throw "文件太小（$size 字节），可能不是正确内容" }
        Write-Host "  ✅ 已下载 $([math]::Round($size/1KB)) KB" -ForegroundColor Green
        Write-Host "     来源：$u"
        $ok = $true
        break
    } catch {
        Write-Host "  ✗ $u" -ForegroundColor DarkGray
        Write-Host "    $($_.Exception.Message)" -ForegroundColor DarkGray
        if (Test-Path -LiteralPath $dest) { Remove-Item -LiteralPath $dest -Force }
    }
}

if (-not $ok) {
