function makeBaseTexture(w, h, radius) {
  var canvas = document.createElement('canvas');
  canvas.width = Math.max(8, Math.round(w));
  canvas.height = Math.max(8, Math.round(h));
  var ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  var g = ctx.createLinearGradient(0, 0, 0, canvas.height);
  g.addColorStop(0, '#1b0533');
  g.addColorStop(0.45, '#2b0a45');
  g.addColorStop(1, '#12032a');
  ctx.fillStyle = g;
  ctx.beginPath();
  var r = Math.min(radius, canvas.width / 2, canvas.height / 2);
  ctx.moveTo(r, 0);
  ctx.lineTo(canvas.width - r, 0);
  ctx.quadraticCurveTo(canvas.width, 0, canvas.width, r);
  ctx.lineTo(canvas.width, canvas.height - r);
  ctx.quadraticCurveTo(canvas.width, canvas.height, canvas.width - r, canvas.height);
  ctx.lineTo(r, canvas.height);
  ctx.quadraticCurveTo(0, canvas.height, 0, canvas.height - r);
  ctx.lineTo(0, r);
  ctx.quadraticCurveTo(0, 0, r, 0);
  ctx.closePath();
  ctx.fill();
  var band = ctx.createLinearGradient(0, canvas.height * 0.35, 0, canvas.height * 0.5);
  band.addColorStop(0, 'rgba(255,60,190,0)');
  band.addColorStop(0.5, 'rgba(255,60,190,0.22)');
  band.addColorStop(1, 'rgba(255,60,190,0)');
  ctx.fillStyle = band;
  ctx.fill();
  return PIXI.Texture.from(canvas);
}

